// Extraer el comando del body de Alexa y preparar para el agente
const body = $input.first().json.body;
const comando = body.comando || body.tarea || body.contenido || '';
const accion = body.action || 'comando_libre';
const dispositivo = body.dispositivo || '';
const accionDisp = body.accion || '';

// Construir prompt natural para el agente
let prompt = '';

switch(accion) {
  case 'control_dispositivo':
    prompt = `${accionDisp} ${dispositivo}`;
    break;
  case 'consultar_estado':
    const elemento = body.elemento || 'casa';
    prompt = `Cual es el estado de ${elemento}?`;
    break;
  case 'ejecutar_tarea':
    const tarea = body.tarea || '';
    prompt = `Ejecuta la tarea: ${tarea}`;
    break;
  case 'resumen_diario':
    prompt = 'Dame un resumen del estado actual de la casa: temperatura, luces encendidas, puertas, etc.';
    break;
  default:
    prompt = comando || `${accionDisp} ${dispositivo}`.trim();
}

return [{ json: { prompt } }];

// Formatear la respuesta del agente para Alexa
const agentResponse = $input.first().json.output || $input.first().json.text || 'Comando ejecutado.';

// Limpiar respuesta para que suene bien en Alexa
let mensaje = agentResponse
  .replace(/\*\*/g, '')  // Quitar markdown bold
  .replace(/\*/g, '')    // Quitar markdown italic
  .replace(/#+\s/g, '')  // Quitar headers markdown
  .replace(/`[^`]*`/g, (match) => match.replace(/`/g, ''))  // Quitar backticks
  .replace(/\n/g, '. ') // Saltos de linea a puntos
  .replace(/\s+/g, ' ') // Multiples espacios
  .trim();

// Limitar longitud para Alexa (max ~200 palabras para buena UX)
const words = mensaje.split(' ');
if (words.length > 80) {
  mensaje = words.slice(0, 80).join(' ') + '. Y mas.';
}

return [{
  json: {
    mensaje: mensaje,
    status: 'ok',
    source: 'n8n-ai-agent-via-ha-mcp',
    timestamp: new Date().toISOString()
  }
}];
